CREATE TABLE accounts (id BIGSERIAL PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, phone VARCHAR(24), role VARCHAR(16) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE listings (id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES accounts(id), title VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, city VARCHAR(100) NOT NULL, locality VARCHAR(120) NOT NULL, landmark VARCHAR(160), address VARCHAR(500), description VARCHAR(1000), monthly_rent INTEGER NOT NULL CHECK (monthly_rent >= 0), deposit INTEGER NOT NULL CHECK (deposit >= 0), available_beds INTEGER NOT NULL DEFAULT 1, gender_preference VARCHAR(20) NOT NULL DEFAULT 'Any', verified BOOLEAN NOT NULL DEFAULT FALSE, demo BOOLEAN NOT NULL DEFAULT FALSE, available BOOLEAN NOT NULL DEFAULT TRUE, cover_image VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE listing_amenities (listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, amenity VARCHAR(80) NOT NULL, PRIMARY KEY(listing_id, amenity));
CREATE INDEX listings_city_locality_idx ON listings(city, locality); CREATE INDEX listings_rent_idx ON listings(monthly_rent);
CREATE TABLE favorites (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT favorite_once UNIQUE(tenant_id, listing_id));
CREATE TABLE bookings (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES accounts(id), listing_id BIGINT NOT NULL REFERENCES listings(id), move_in_date DATE NOT NULL, monthly_rent INTEGER NOT NULL, deposit INTEGER NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE visits (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES accounts(id), listing_id BIGINT NOT NULL REFERENCES listings(id), requested_for TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL, note VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES accounts(id), listing_id BIGINT NOT NULL REFERENCES listings(id), rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), body VARCHAR(1200), demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT review_once UNIQUE(tenant_id, listing_id));
